const clients = new Map(); // client_id -> Map(key -> value)

function isNonEmptyString(v) {
  return typeof v === 'string' && v.length > 0;
}

class ToolError extends Error {
  constructor(message, code) {
    super(message);
    this.code = code;
  }
}

function validateNonEmpty(value, name) {
  if (!isNonEmptyString(value)) {
    throw new ToolError(`${name} must be a non-empty string`, -32602);
  }
}

function requireClient(client_id) {
  if (!clients.has(client_id)) {
    throw new ToolError(`unknown client: ${client_id}`, -32602);
  }
}

export async function listTools() {
  return [
    {
      name: 'open_client',
      description: 'Open a client with an independent key/value map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Unique non-empty client identifier.' }
        },
        required: ['client_id'],
        additionalProperties: false
      }
    },
    {
      name: 'client_put',
      description: 'Write a key/value pair into the owning client\'s map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' },
          value: { type: 'string' }
        },
        required: ['client_id', 'key', 'value'],
        additionalProperties: false
      }
    },
    {
      name: 'client_get',
      description: 'Read a key from the owning client\'s map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' }
        },
        required: ['client_id', 'key'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'open_client': {
      validateNonEmpty(args.client_id, 'client_id');
      if (!clients.has(args.client_id)) {
        clients.set(args.client_id, new Map());
      }
      return { content: [{ type: 'text', text: `client ${args.client_id} opened` }] };
    }
    case 'client_put': {
      validateNonEmpty(args.client_id, 'client_id');
      validateNonEmpty(args.key, 'key');
      validateNonEmpty(args.value, 'value');
      requireClient(args.client_id);
      clients.get(args.client_id).set(args.key, args.value);
      return { content: [{ type: 'text', text: 'ok' }] };
    }
    case 'client_get': {
      validateNonEmpty(args.client_id, 'client_id');
      validateNonEmpty(args.key, 'key');
      requireClient(args.client_id);
      const map = clients.get(args.client_id);
      if (!map.has(args.key)) {
        throw new ToolError(`unknown key: ${args.key}`, -32602);
      }
      return { content: [{ type: 'text', text: map.get(args.key) }] };
    }
    default:
      throw new ToolError(`unknown tool: ${name}`, -32601);
  }
}
